PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT DISTINCT ?result WHERE {
  ?employee pv:areaOfExpertise <http://ld.company.org/prod-instances/prod-cat-Sensor> .
  ?employee a pv:Employee ;
             pv:name ?result .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT DISTINCT ?supplier WHERE {
  ?product a pv:Product ; pv:hasCategory <http://ld.company.org/prod-instances/prod-cat-Compensator> .
  ?product pv:hasSupplier ?supplier .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?result WHERE {
  ?service a pv:Service ;
           pv:price ?price .
  ?price pv:amount ?amount ;
         pv:currency "EUR" .
  ?employee a pv:Employee ;
             pv:hasProductManager ?product .
  ?product pv:eligibleFor ?service .
  FILTER(?amount = (SELECT MAX(?maxAmount) WHERE {
    ?service2 a pv:Service ;
               pv:price ?price2 .
    ?price2 pv:amount ?maxAmount ;
             pv:currency "EUR" .
  }))
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT DISTINCT ?result WHERE {
  <http://ld.company.org/prod-instances/hw-U990-5234138> pv:compatibleProduct ?result .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT DISTINCT ?city WHERE {
  ?supplier a pv:Supplier ; pv:country "United States" ;
             pv:hasProductManager ?product .
  ?product pv:hasCategory ?category ;
           pv:id "LCDs" .
  ?address pv:addressCountryCode "US" ;
            pv:addressLocality ?city .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?supplierName ?country ?priceAmount WHERE {
  ?product a pv:Hardware ;
           pv:price ?price .
  ?price pv:amount ?priceAmount ;
          pv:currency "EUR" .
  ?product pv:hasSupplier ?supplier .
  ?supplier pv:name ?supplierName ;
             pv:country ?country .
} ORDER BY DESC(?priceAmount) LIMIT 5 OFFSET 5

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?category (MIN(?weight_g) AS ?lightest) (MAX(?weight_g) AS ?heaviest) WHERE {
  ?product a pv:Hardware ; pv:hasCategory ?category ; pv:weight_g ?weight_g .
} GROUP BY ?category ORDER BY ?category

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?product ?compatibleProduct (?priceDifference AS ?result) WHERE {
  ?product a pv:Product ;
           pv:compatibleProduct ?compatibleProduct ;
           pv:price ?price .
  ?compatibleProduct pv:price ?compatiblePrice .
  BIND((?price - ?compatiblePrice) AS ?priceDifference)
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?name ?email ?phone ?departmentName ?directReportName WHERE {
  ?employee a pv:Employee ;
             pv:name ?name ;
             pv:email ?email ;
             pv:phone ?phone ;
             pv:memberOf ?department ;
             pv:hasDirectReport ?directReport .
  ?department a pv:Department ;
               pv:name ?departmentName .
  OPTIONAL { ?directReport pv:name ?directReportName }
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?bom (AVG(?price) AS ?averageCost) WHERE {
  ?bom a pv:BillOfMaterial ;
        pv:hasBomPart ?part .
  ?part pv:hasPart ?hardware ;
         pv:price ?price .
} GROUP BY ?bom ORDER BY DESC(?averageCost) LIMIT 1

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?supplier (AVG(?reliabilityIndex) AS ?averageReliability) WHERE {
  ?product a pv:Product ; pv:hasSupplier ?supplier .
  ?part a pv:BomPart ; pv:hasPart ?product ; pv:reliabilityIndex ?reliabilityIndex .
} GROUP BY ?supplier ORDER BY DESC(?averageReliability) LIMIT 5

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT DISTINCT ?bom WHERE {
  ?bom a pv:BillOfMaterial ;
        pv:hasBomPart ?part .
  ?part pv:hasSupplier ?supplier ;
         pv:country "Poland" .
}
